insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-so-188', 'chemistry-solutions', 'chemistry', 'A binary liquid shows $\Delta H_{\mathrm{mix}}$ negative and total vapour pressure below the Raoult prediction at every composition. Distillation of this pair commonly yields', '["a maximum-boiling azeotrope","a minimum-boiling azeotrope","an ideal vapour of unchanged composition","no condensate at any temperature"]'::jsonb, 0, 'Negative deviation produces a minimum in p versus x and therefore a maximum-boiling azeotrope.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'ideal-nonideal') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
